        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def first_below_zero(items):
    """Walk ``(line, Movement)`` pairs in date order (stable per day).

    Returns ``(line, movement, balance)`` for the first movement that takes
    its product below zero, or None.
    """
    balances = {}
    for line, move in sorted(items, key=lambda item: item[1].date):
        balance = balances.get(move.sku, 0) + move.quantity
        if balance < 0:
            return line, move, balance
        balances[move.sku] = balance
    return None


def parse_movements(text, catalog):
    """Parse movements text; returns Movements in file order."""
