        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r (want a real YYYY-MM-DD date)" % date_text)
        sku = normalise_sku(sku_text)
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku_text)
        if not QTY_RE.fullmatch(qty_text):
            raise ParseError(number, "bad quantity %r (want a whole number, optionally signed)" % qty_text)
        quantity = to_int(qty_text)
        if quantity is None:
            raise ParseError(number, "quantity %r is too large" % qty_text)
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
