"""Exact-to-the-penny pricing."""

import decimal
from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import List

from .catalog import CENT, TAX_RATES

ZERO = Decimal("0.00")


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _round(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _negative(amount):
    """-amount, but zero stays ``0.00`` (never ``-0.00``)."""
    return ZERO if amount == 0 else -amount


def _volume_rate(quantity):
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def _share_out(total_pennies, nets):
    """Split ``total_pennies`` over ``nets`` (pennies) proportionally.

    Floor each share; leftover pennies go one each to the biggest lost
    fractions, the earlier line first on a tie.
    """
    base = sum(nets)
    if base <= 0:
        return [0] * len(nets)
    shares = [total_pennies * net // base for net in nets]
    remainders = [total_pennies * net % base for net in nets]
    leftover = total_pennies - sum(shares)
    by_loss = sorted(range(len(nets)), key=lambda i: (-remainders[i], i))
    for i in by_loss[:leftover]:
        shares[i] += 1
    return shares


def price_order(order, catalog):
    """Price ``order`` (anything with ``.lines`` of (sku, quantity)) against ``catalog``."""
    with decimal.localcontext() as ctx:
        ctx.prec = 200
        lines = []
        for sku, quantity in order.lines:
            unit = catalog[sku].price
            gross = _round(unit * quantity)
            discount = _negative(_round(gross * _volume_rate(quantity)))
            lines.append(QuoteLine(sku, quantity, unit, gross, discount, _round(gross + discount)))
        subtotal = _round(sum((line.net for line in lines), ZERO))
        if subtotal >= Decimal("500.00"):
            order_discount = _negative(_round(subtotal * Decimal("0.03")))
        else:
            order_discount = ZERO
        pennies = int(-order_discount * 100)
        shares = _share_out(pennies, [int(line.net * 100) for line in lines])
        tax = ZERO
        for line, share in zip(lines, shares):
            taxable = line.net - Decimal(share) / 100
            tax += _round(taxable * TAX_RATES[catalog[line.sku].tax])
        tax = _round(tax)
        total = _round(subtotal + order_discount + tax)
        return Quote(lines, subtotal, order_discount, tax, total)
