"""Stock levels, the buy list and per-SKU history."""

from .movements import first_below_zero


def in_count_order(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda move: move.date)


def stock_levels(catalog, movements):
    """Dict SKU -> quantity on the shelf, for every product (0 if never moved)."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
