"""What has shipped, what can ship, and the status of an order."""

import math
from dataclasses import dataclass

from .shelves import in_count_order


@dataclass(frozen=True)
class LinePlan:
    sku: str
    ordered: int
    shipped_before: int
    ship: int

    @property
    def owed(self):
        return self.ordered - self.shipped_before

    @property
    def shipped_after(self):
        return self.shipped_before + self.ship

    @property
    def backordered(self):
        return self.ordered - self.shipped_after


def shipped_so_far(order, movements):
    """Dict SKU -> units already shipped for ``order`` (capped at the quantity ordered)."""
    note = "order " + order.id
    sent = {}
    for move in movements:
        if move.note == note and move.quantity < 0:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return {sku: min(qty, sent.get(sku, 0)) for sku, qty in order.lines}


def available_on(sku, date, movements):
    """Most that can leave on ``date`` without any later movement going below zero."""
    balance = 0
    at_date = 0
    lowest_later = math.inf
    for move in in_count_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        else:
            lowest_later = min(lowest_later, balance)
    return max(0, min(at_date, lowest_later))


def plan_fulfil(order, movements, date):
    """One LinePlan per order line."""
    before = shipped_so_far(order, movements)
    plans = []
    for sku, ordered in order.lines:
        owed = ordered - before[sku]
        ship = min(owed, available_on(sku, date, movements))
        plans.append(LinePlan(sku, ordered, before[sku], ship))
    return plans


def status_of_order(order, shipped):
    """``complete``, ``open`` or ``partial`` from a SKU -> shipped dict."""
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if not any(shipped[sku] > 0 for sku, _ in order.lines):
        return "open"
    return "partial"
